import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long r = sc.nextLong();
        long x = sc.nextLong();
        long y = sc.nextLong();
        long targetX = sc.nextLong();
        long targetY = sc.nextLong();

        long dx = targetX - x;
        long dy = targetY - y;
        long distanceSquared = dx * dx + dy * dy;

        long steps = (long) Math.ceil(Math.sqrt(distanceSquared) / (2.0 * r));

        while (steps > 0) {
            long reach = 2L * r * (steps - 1);
            if (reach * reach < distanceSquared) break;
            steps--;
        }

        while (true) {
            long reach = 2L * r * steps;
            if (reach * reach >= distanceSquared) break;
            steps++;
        }

        System.out.println(steps);
    }
}

